const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=new Set();try{selected=new Set(JSON.parse(localStorage.getItem('ledger-selection')||'[]').filter(id=>contacts.some(c=>c.id===id)))}catch{}let selectedOnly=false;
function visible(){let q=$('#search').value.toLowerCase();return contacts.filter(c=>(!selectedOnly||selected.has(c.id))&&(!$('#area').value||c.area===$('#area').value)&&(!$('#role').value||c.role===$('#role').value)&&[c.name,c.firm,c.email,c.city].some(v=>v.toLowerCase().includes(q)))}
function render(){const list=visible();$('#rows').innerHTML=list.map(c=>`<tr><td><input type="checkbox" data-check="${c.id}" aria-label="Select ${esc(c.name)}" ${selected.has(c.id)?'checked':''}></td><td><div class="person"><div class="initial">${c.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><button data-detail="${c.id}">${esc(c.name)}</button><div class="sub"><span class="role">${c.role}</span></div></div></div></td><td>${esc(c.firm)}<div class="sub">${esc(c.city)} · ${c.area}</div></td><td><a class="email" href="mailto:${esc(c.email)}">${esc(c.email)}</a><div class="sub"><span class="dot">●</span> Published · verification pending</div></td><td>${c.phone}<div class="sub">Business contact number</div></td><td><button class="detail" data-detail="${c.id}" aria-label="View ${esc(c.name)}">↗</button></td></tr>`).join('');$('#count').textContent=`Showing ${list.length} of 20 contacts`;$('#selection').textContent=`${selected.size} selected for sample`;$('#selcount').textContent=selected.size;$('#empty').hidden=!!list.length;$('#selectall').checked=!!list.length&&list.every(c=>selected.has(c.id));$('#selectall').indeterminate=list.some(c=>selected.has(c.id))&&!$('#selectall').checked;$('#export').textContent=selected.size?`↓  Export selected (${selected.size})`:'↓  Export CSV';try{localStorage.setItem('ledger-selection',JSON.stringify([...selected]))}catch{}}
function show(id){let c=contacts.find(c=>c.id===id);$('#detailbody').innerHTML=`<div class="eyebrow">Contact ${String(c.id).padStart(2,'0')} / Research evidence</div><h2>${esc(c.name)}</h2><div style="color:var(--muted)">${esc(c.firm)} · ${c.role}</div><div class="fields"><div><label>Published email</label><a href="mailto:${esc(c.email)}">${esc(c.email)}</a><div class="sub">${c.emailStatus}</div></div><div><label>Business phone / location</label>${c.phone} · ${esc(c.city)}</div><div><label>Client-facing role evidence</label><p>${esc(c.evidence)}</p></div><div><label>Firm size & qualification notes</label><p>${esc(c.size)}</p></div><div><label>Sources · retrieved ${c.checked}</label><a href="${c.source}" target="_blank" rel="noopener">Contact evidence ↗</a>${c.source!==c.roleSource?` &nbsp; · &nbsp; <a href="${c.roleSource}" target="_blank" rel="noopener">Role evidence ↗</a>`:''}</div></div><div class="notice" style="margin:0">Needs qualification · Confirm named mailbox ownership, deliverability and fewer than 10 staff before acceptance.</div>`;$('#modal').showModal()}
document.addEventListener('click',e=>{let d=e.target.closest('[data-detail]');if(d)show(Number(d.dataset.detail));let p=e.target.closest('[data-page]');if(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('visible',x.id===p.dataset.page));document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===p))}});$('#rows').addEventListener('change',e=>{if(e.target.dataset.check){let id=Number(e.target.dataset.check);e.target.checked?selected.add(id):selected.delete(id);render()}});$('#selectall').onchange=e=>{visible().forEach(c=>e.target.checked?selected.add(c.id):selected.delete(c.id));render()};['search','area','role'].forEach(id=>$('#'+id).addEventListener('input',render));function tab(v){selectedOnly=v;$('#alltab').classList.toggle('active',!v);$('#selectedtab').classList.toggle('active',v);render()}$('#alltab').onclick=()=>tab(false);$('#selectedtab').onclick=()=>tab(true);$('#reset').onclick=()=>{$('#search').value=$('#area').value=$('#role').value='';tab(false)};$('#sample').onclick=()=>{selected=new Set(contacts.slice(0,10).map(c=>c.id));render();toast('First 10 selected. Qualification is still pending.')};$('.close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
$('#export').onclick=()=>{const list=selected.size?contacts.filter(c=>selected.has(c.id)):visible();if(!list.length){toast('No contacts to export.');return}const keys=['name','firm','role','email','phone','city','area','emailStatus','status','evidence','size','source','roleSource','checked'];const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\uFEFF'+[keys,...list.map(c=>keys.map(k=>c[k]))].map(r=>r.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));let a=document.createElement('a');a.href=url;a.download=`accounting-research-${list.length}-contacts.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${list.length} contacts exported with evidence and qualification notes.`)};render();
